// Chronos Input hook: observe Ultrascripts and translate Chronos slash commands
// into ordinary narrative actions. Returning stop from onInput is a platform
// error, so handled commands remain safe, valid inputs for the generation loop.
const modifier = (text) => {
  ChronosV2.initialize();
  ChronosV2.observeHeartbeat();
  const handled = ChronosV2.handleInput(text);
  return { text: handled.text };
};
modifier(text);

code.onModelContext:
// @cache-compatible
// Chronos Context hook: advance the clock, publish its player-facing display,
// and append an authoritative timestamp without changing the cached prefix.
const modifier = (text) => {
  ChronosV2.initialize();
  ChronosV2.syncSettings();
  ChronosV2.advanceToCurrentAction();
  ChronosV2.applyPendingCommand();
  ChronosV2.advanceWeather();
  ChronosV2.recordSnapshot();
  ChronosV2.publishStoryCard();

  if (!ChronosV2.enabled()) {
    ChronosV2.clearWidget();
    if (ChronosV2.hasNotice()) ChronosV2.publishToast();
    else ChronosV2.clearToast();
    return { text };
  }

  if (!ChronosV2.hasTrackedDisplay()) {
    ChronosV2.clearWidget();
    if (ChronosV2.hasNotice()) ChronosV2.publishToast();
    else ChronosV2.clearToast();
    return { text };
  }

  if (ChronosV2.widgetAvailable() && ChronosV2.publishWidget()) {
    if (ChronosV2.hasNotice()) ChronosV2.publishToast();
    else ChronosV2.clearToast();
  } else {
    ChronosV2.publishToast();
  }

  return { text: ChronosV2.appendContext(text) };
};
modifier(text);

code.sharedLibrary:
// ============================================================
// LIBRARY - Chronos V2
// ============================================================
// An in-game clock, Gregorian calendar, and seasonal weather for AI Dungeon.
//
// Chronos owns time, date, and simple seasonal weather, without simulating
// astronomy or real-world time. Lifecycle behavior stays in the matching
// Input and Context files; this Library file contains shared helpers only.

globalThis.ChronosV2 = (function createChronosV2() {
  'use strict';

  var VERSION = 3;
  var SETTINGS_CARD = 'Chronos Settings';
  var WIDGET_CARD = 'ultrascripts:state:widget';
  var HEARTBEAT_CARD = 'ultrascripts:heartbeat';
  var MONTH_NAMES = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];
  var WEEKDAY_NAMES = [
    'Sunday', 'Monday', 'Tuesday', 'Wednesday',
    'Thursday', 'Friday', 'Saturday'
  ];
  var ACTIVE_WIDGET_ID = 'chronos-clock';
  var MAX_WIDGETS = 40;
  var MAX_CHRONOS_HISTORY = 500;
  var MAX_YEAR = 999999;
  var WEATHER_PROFILES = {
    Spring: [30, 35, 35, 0],
    Summer: [60, 25, 15, 0],
    Autumn: [25, 35, 40, 0],
    Winter: [10, 25, 20, 45]
  };
  var WEATHER_NAMES = ['Sunny', 'Cloudy', 'Rain', 'Snow'];
  var SEASON_NAMES = ['Spring', 'Summer', 'Autumn', 'Winter'];
  var WEATHER_STAY_CHANCE = 0.97;

  function isRecord(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
  }

  function currentActionCount() {
    var value = typeof info !== 'undefined' && info ? Number(info.actionCount) : 0;
    return isFinite(value) && value >= 0 ? Math.floor(value) : 0;
  }

  function defaultClock() {
    return { year: 2026, month: 6, day: 1, hour: 8, minute: 0 };
  }

  function initialize() {
    if (!isRecord(globalThis.state)) return null;

    var previous = isRecord(state.chronos)
      ? state.chronos
      : {};

    var upgradingV2 = previous.version === 2;
    if (previous.version !== VERSION && !upgradingV2) {
      previous = {
        version: VERSION,
        clock: defaultClock(),
        settings: {
          enabled: true,
          trackTime: true,
          trackDate: true,
          trackWeather: true,
          minutesPerTurn: 2,
          clockFormat: '12-hour',
          dateFormat: 'Long'
        },
        lastActionCount: currentActionCount(),
        notice: '',
        toastSequence: 0,
        pendingCommand: null,
        timeline: {},
        weather: null,
        ultrascripts: {}
      };
      state.chronos = previous;
    } else if (upgradingV2) {
      previous.version = VERSION;
    }

    previous.clock = normalizeClock(isRecord(previous.clock) ? previous.clock : defaultClock());
    previous.settings = isRecord(previous.settings) ? previous.settings : {};
    if (typeof previous.settings.enabled !== 'boolean') previous.settings.enabled = true;
    delete previous.settings.paused;
    if (typeof previous.settings.trackTime !== 'boolean') previous.settings.trackTime = true;
    if (typeof previous.settings.trackDate !== 'boolean') previous.settings.trackDate = true;
    if (typeof previous.settings.trackWeather !== 'boolean') {
      previous.settings.trackWeather = true;
    }
    delete previous.settings.showTimePhase;
    previous.settings.minutesPerTurn = clampInteger(
      previous.settings.minutesPerTurn,
      0,
      1440,
      2
    );
    if (previous.settings.clockFormat !== '24-hour') previous.settings.clockFormat = '12-hour';
    if (['Long', 'ISO', 'American', 'European'].indexOf(previous.settings.dateFormat) === -1) {
      previous.settings.dateFormat = 'Long';
    }
    if (!validInteger(previous.lastActionCount) || Number(previous.lastActionCount) < 0) {
      previous.lastActionCount = currentActionCount();
    } else {
      previous.lastActionCount = Number(previous.lastActionCount);
    }
    if (typeof previous.notice !== 'string') previous.notice = '';
    if (!validInteger(previous.toastSequence) || Number(previous.toastSequence) < 0) {
      previous.toastSequence = 0;
    } else {
      previous.toastSequence = Number(previous.toastSequence) % 2;
    }
    if (!validPendingCommand(previous.pendingCommand)) {
      previous.pendingCommand = null;
    }
    if (!isRecord(previous.timeline)) previous.timeline = {};
    if (!isRecord(previous.ultrascripts)) previous.ultrascripts = {};
    if (upgradingV2) {
      migrateLegacyWeather(previous);
    } else if (!isRecord(previous.weather)) {
      previous.weather = createWeatherState(previous.clock, previous.settings.trackWeather);
    } else {
      previous.weather = normalizeWeatherState(previous.weather, previous.clock);
    }
    if (!isRecord(previous.timeline[String(previous.lastActionCount)])) {
      previous.timeline[String(previous.lastActionCount)] = makeSnapshot(previous);
    }
    return previous;
  }

  function validInteger(value) {
    var number = Number(value);
    return isFinite(number) && Math.floor(number) === number;
  }

  function clampInteger(value, minimum, maximum, fallback) {
    if (value === null || String(value).trim() === '') return fallback;
    var number = Number(value);
    if (!isFinite(number)) return fallback;
    number = Math.floor(number);
    return Math.max(minimum, Math.min(maximum, number));
  }

  function normalizeClock(value) {
    var clock = value || {};
    var fallback = defaultClock();
    var year = clampInteger(clock.year, 1, MAX_YEAR, fallback.year);
    var month = clampInteger(clock.month, 1, 12, fallback.month);
    var day = clampInteger(clock.day, 1, daysInMonth(year, month), fallback.day);
    return {
      year: year,
      month: month,
      day: day,
      hour: clampInteger(clock.hour, 0, 23, fallback.hour),
      minute: clampInteger(clock.minute, 0, 59, fallback.minute)
    };
  }

  function isLeapYear(year) {
    return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  }

  function daysInMonth(year, month) {
    if (month === 2) return isLeapYear(year) ? 29 : 28;
    return [4, 6, 9, 11].indexOf(month) !== -1 ? 30 : 31;
  }

  function copyClock(clock) {
    return {
      year: clock.year,
      month: clock.month,
      day: clock.day,
      hour: clock.hour,
      minute: clock.minute
    };
  }

  function sameClock(left, right) {
    return left.year === right.year && left.month === right.month &&
      left.day === right.day && left.hour === right.hour &&
      left.minute === right.minute;
  }

  function seasonForClock(clock) {
    var date = clock.month * 100 + clock.day;
    if (date >= 1221 || date < 320) return 'Winter';
    if (date >= 922) return 'Autumn';
    if (date >= 621) return 'Summer';
    return 'Spring';
  }

  function displaySeason(chronos) {
    return chronos.weather.manualSeason || seasonForClock(chronos.clock);
  }

  function validWeatherName(value) {
    return WEATHER_NAMES.indexOf(value) !== -1;
  }

  function seedWeatherRandom() {
    return (Math.floor(Math.random() * 4294967296) >>> 0) || 0x6d2b79f5;
  }

  function nextWeatherRandom(weather) {
    var value = weather.randomState >>> 0;
    value ^= value << 13;
    value ^= value >>> 17;
    value ^= value << 5;
    weather.randomState = value >>> 0;
    return weather.randomState / 4294967296;
  }

  function drawWeather(weather, season) {
    var weights = WEATHER_PROFILES[season];
    var choice = nextWeatherRandom(weather) * 100;
    var cumulative = 0;
    for (var index = 0; index < weights.length; index += 1) {
      cumulative += weights[index];
      if (choice < cumulative) return WEATHER_NAMES[index];
    }
    return 'Rain';
  }

  function stepWeather(weather, clock) {
    var season = seasonForClock(clock);
    if (weather.manual || !validWeatherName(weather.condition) ||
        (weather.condition === 'Snow' && season !== 'Winter') ||
        nextWeatherRandom(weather) >= WEATHER_STAY_CHANCE) {
      weather.condition = drawWeather(weather, season);
    }
    weather.clock = copyClock(clock);
    weather.manual = false;
    weather.manualSeason = null;
  }

  function copyWeatherState(weather) {
    return {
      condition: weather.condition,
      randomState: weather.randomState,
      clock: copyClock(weather.clock),
      manual: weather.manual,
      manualSeason: weather.manualSeason
    };
  }

  function createWeatherState(clock, enabled) {
    var weather = {
      condition: null,
      randomState: seedWeatherRandom(),
      clock: copyClock(clock),
      manual: false,
      manualSeason: null
    };
    if (enabled) stepWeather(weather, clock);
    return weather;
  }

  function normalizeWeatherState(value, clock) {
    var randomState = Number(value.randomState);
    var weatherClock = isRecord(value.clock) ? normalizeClock(value.clock) : copyClock(clock);
    var manual = value.manual === true;
    var condition = validWeatherName(value.condition) &&
      (value.condition !== 'Snow' || seasonForClock(weatherClock) === 'Winter' || manual)
      ? value.condition : null;
    return {
      condition: condition,
      randomState: validInteger(randomState) && randomState > 0 &&
        randomState <= 4294967295 ? randomState : seedWeatherRandom(),
      clock: weatherClock,
      manual: manual && condition !== null,
      manualSeason: manual && SEASON_NAMES.indexOf(value.manualSeason) !== -1
        ? value.manualSeason : null
    };
  }

  function makeSnapshot(chronos) {
    return {
      clock: copyClock(chronos.clock),
      // The snapshot clock is also the weather clock after every update.
      weather: {
        condition: chronos.weather.condition,
        randomState: chronos.weather.randomState,
        manual: chronos.weather.manual,
        manualSeason: chronos.weather.manualSeason
      }
    };
  }

  function migrateLegacyWeather(chronos) {
    var keys = Object.keys(chronos.timeline).filter(function (key) {
      return /^\d+$/.test(key) && isRecord(chronos.timeline[key]);
    }).sort(function (left, right) {
      return Number(left) - Number(right);
    });
    var weather = {
      condition: null,
      randomState: seedWeatherRandom(),
      clock: copyClock(chronos.clock),
      manual: false,
      manualSeason: null
    };
    var activeWeather = null;
    keys.forEach(function (key) {
      var oldSnapshot = chronos.timeline[key];
      var clock = normalizeClock(isRecord(oldSnapshot.clock)
        ? oldSnapshot.clock : oldSnapshot);
      if (!validWeatherName(weather.condition) || !sameClock(weather.clock, clock)) {
        stepWeather(weather, clock);
      }
      chronos.timeline[key] = makeSnapshot({ clock: clock, weather: weather });
      if (Number(key) === chronos.lastActionCount) {
        activeWeather = copyWeatherState(weather);
      }
    });
    chronos.weather = activeWeather || createWeatherState(
      chronos.clock,
      chronos.settings.trackWeather
    );
    if (activeWeather && !sameClock(chronos.weather.clock, chronos.clock)) {
      stepWeather(chronos.weather, chronos.clock);
    }
    if (!chronos.settings.trackWeather) chronos.weather.condition = null;
    chronos.timeline[String(chronos.lastActionCount)] = makeSnapshot(chronos);
  }

  function advanceWeather() {
    var chronos = initialize();
    if (!chronos) return;
    if (!chronos.settings.enabled || !chronos.settings.trackWeather) {
      chronos.weather.condition = null;
      chronos.weather.clock = copyClock(chronos.clock);
      chronos.weather.manual = false;
      chronos.weather.manualSeason = null;
      return;
    }
    if (!validWeatherName(chronos.weather.condition) ||
        !sameClock(chronos.weather.clock, chronos.clock)) {
      stepWeather(chronos.weather, chronos.clock);
    }
  }

  function daysBeforeYear(year) {
    var previousYear = year - 1;
    return previousYear * 365 + Math.floor(previousYear / 4) -
      Math.floor(previousYear / 100) + Math.floor(previousYear / 400);
  }

  function daysBeforeMonth(year, month) {
    var total = 0;
    for (var currentMonth = 1; currentMonth < month; currentMonth += 1) {
      total += daysInMonth(year, currentMonth);
    }
    return total;
  }

  function clockToMinuteIndex(clock) {
    var days = daysBeforeYear(clock.year) + daysBeforeMonth(clock.year, clock.month) +
      clock.day - 1;
    return days * 1440 + clock.hour * 60 + clock.minute;
  }

  function maxMinuteIndex() {
    return (daysBeforeYear(MAX_YEAR + 1) * 1440) - 1;
  }

  function clockFromMinuteIndex(value) {
    var minuteIndex = Math.max(0, Math.min(maxMinuteIndex(), Math.trunc(value)));
    var dayIndex = Math.floor(minuteIndex / 1440);
    var minuteOfDay = minuteIndex % 1440;
    var low = 1;
    var high = MAX_YEAR;

    while (low < high) {
      var middle = Math.ceil((low + high) / 2);
      if (daysBeforeYear(middle) <= dayIndex) low = middle;
      else high = middle - 1;
    }

    var year = low;
    var dayOfYear = dayIndex - daysBeforeYear(year);
    var month = 1;
    while (dayOfYear >= daysInMonth(year, month)) {
      dayOfYear -= daysInMonth(year, month);
      month += 1;
    }

    return {
      year: year,
      month: month,
      day: dayOfYear + 1,
      hour: Math.floor(minuteOfDay / 60),
      minute: minuteOfDay % 60
    };
  }

  function addMinutes(amount) {
    var chronos = initialize();
    if (!chronos) return;
    var amountAsNumber = Number(amount);
    if (!isFinite(amountAsNumber)) return;
    chronos.clock = clockFromMinuteIndex(
      clockToMinuteIndex(chronos.clock) + Math.trunc(amountAsNumber)
    );
  }

  function advanceToCurrentAction() {
    var chronos = initialize();
    if (!chronos) return;
    var actionCount = currentActionCount();
    var delta = actionCount - chronos.lastActionCount;

    if (delta < 0) {
      var snapshot = chronos.timeline[String(actionCount)] ||
        latestSnapshotAtOrBefore(chronos.timeline, actionCount);
      if (isRecord(snapshot)) {
        chronos.clock = normalizeClock(isRecord(snapshot.clock) ? snapshot.clock : snapshot);
        chronos.weather = isRecord(snapshot.weather)
          ? normalizeWeatherState(snapshot.weather, chronos.clock)
          : createWeatherState(chronos.clock, chronos.settings.trackWeather);
      } else if (chronos.settings.enabled) {
        addMinutes(-chronos.settings.minutesPerTurn);
      }
      discardFutureSnapshots(chronos.timeline, actionCount);
    } else if (delta > 0 && chronos.settings.enabled &&
        !chronos.pendingCommand) {
      // actionCount includes player actions, AI output, and other platform
      // actions. One new Context update represents one Chronos turn.
      addMinutes(chronos.settings.minutesPerTurn);
    }
    chronos.lastActionCount = actionCount;
  }

  function latestSnapshotAtOrBefore(timeline, actionCount) {
    var best = null;
    var bestCount = -1;
    Object.keys(timeline).forEach(function (key) {
      if (!/^\d+$/.test(key) || !isRecord(timeline[key])) return;
      var count = Number(key);
      if (count <= actionCount && count > bestCount) {
        best = timeline[key];
        bestCount = count;
      }
    });
    return best;
  }

  function recordSnapshot() {
    var chronos = initialize();
    if (!chronos) return;
    var actionCount = currentActionCount();
    chronos.timeline[String(actionCount)] = makeSnapshot(chronos);
    var keys = Object.keys(chronos.timeline).map(function (key) {
      return { key: key, number: Number(key) };
    }).filter(function (item) {
      if (!/^\d+$/.test(item.key) || !isFinite(item.number)) {
        delete chronos.timeline[item.key];
        return false;
      }
      return true;
    }).sort(function (left, right) {
      return right.number - left.number;
    });
    for (var index = MAX_CHRONOS_HISTORY; index < keys.length; index += 1) {
      delete chronos.timeline[keys[index].key];
    }
  }

  function discardFutureSnapshots(timeline, actionCount) {
    Object.keys(timeline || {}).forEach(function (key) {
      var number = Number(key);
      if (isFinite(number) && number > actionCount) delete timeline[key];
    });
  }

  function weekdayIndex(clock) {
    return (daysBeforeYear(clock.year) + daysBeforeMonth(clock.year, clock.month) +
      clock.day) % 7;
  }

  function pad2(value) {
    return String(value).padStart(2, '0');
  }

  function formatTime() {
    var chronos = initialize();
    if (!chronos) return '';
    var clock = chronos.clock;
    if (chronos.settings.clockFormat === '24-hour') {
      return pad2(clock.hour) + ':' + pad2(clock.minute);
    }
    var suffix = clock.hour >= 12 ? 'PM' : 'AM';
    var hour = clock.hour % 12 || 12;
    return hour + ':' + pad2(clock.minute) + ' ' + suffix;
  }

  function formatTimePhase() {
    var chronos = initialize();
    if (!chronos) return '';
    var hour = chronos.clock.hour;
    if (hour < 3) return 'After Midnight';
    if (hour < 5) return 'Predawn';
    if (hour < 7) return 'Dawn';
    if (hour < 10) return 'Morning';
    if (hour < 12) return 'Late Morning';
    if (hour < 14) return 'Midday';
    if (hour < 17) return 'Afternoon';
    if (hour < 20) return 'Evening';
    return 'Night';
  }

  function showsTimePhase() {
    var chronos = initialize();
    return !!(chronos && chronos.settings.trackTime);
  }

  function formatContextTime() {
    return formatTime() + (showsTimePhase() ? ' (' + formatTimePhase() + ')' : '');
  }

  function formatDate() {
    var chronos = initialize();
    if (!chronos) return '';
    var clock = chronos.clock;
    return WEEKDAY_NAMES[weekdayIndex(clock)] + ', ' +
      MONTH_NAMES[clock.month - 1] + ' ' + clock.day + ', ' + clock.year;
  }

  function formatDisplayDate() {
    var chronos = initialize();
    if (!chronos) return '';
    var clock = chronos.clock;
    var year = String(clock.year).padStart(4, '0');
    if (chronos.settings.dateFormat === 'ISO') {
      return year + '-' + pad2(clock.month) + '-' + pad2(clock.day);
    }
    if (chronos.settings.dateFormat === 'American') {
      return pad2(clock.month) + '/' + pad2(clock.day) + '/' + year;
    }
    if (chronos.settings.dateFormat === 'European') {
      return pad2(clock.day) + '/' + pad2(clock.month) + '/' + year;
    }
    return formatDate();
  }

  function formatWidgetDate() {
    var chronos = initialize();
    if (!chronos) return '';
    if (chronos.settings.dateFormat !== 'Long') return formatDisplayDate();
    var clock = chronos.clock;
    return WEEKDAY_NAMES[weekdayIndex(clock)].slice(0, 3) + ', ' +
      MONTH_NAMES[clock.month - 1].slice(0, 3) + ' ' + clock.day + ', ' + clock.year;
  }

  function formatTimestamp() {
    return formatContextTime() + ' on ' + formatDate();
  }

  function formatDisplayTimestamp() {
    var values = [formatTime()];
    if (showsTimePhase()) values.push(formatTimePhase());
    values.push(formatDisplayDate());
    return values.join(' · ');
  }

  function hasTrackedDisplay() {
    var chronos = initialize();
    return !!(chronos && (chronos.settings.trackTime || chronos.settings.trackDate ||
      (chronos.settings.trackWeather && validWeatherName(chronos.weather.condition))));
  }

  function formatTrackedDisplay(shortDate) {
    var chronos = initialize();
    if (!chronos) return '';
    var values = [];
    if (chronos.settings.trackTime) values.push(formatTime());
    if (showsTimePhase()) values.push(formatTimePhase());
    if (chronos.settings.trackDate) {
      values.push(shortDate ? formatWidgetDate() : formatDisplayDate());
    }
    if (chronos.settings.trackWeather && validWeatherName(chronos.weather.condition)) {
      values.push(displaySeason(chronos));
      values.push(chronos.weather.condition);
    }
    return values.join(' · ');
  }

  function widgetHtml() {
    var chronos = initialize();
    if (!chronos) return '';
    var sections = [];
    var clockLines = [];
    if (chronos.settings.trackTime) {
      clockLines.push('<span style="display:flex;align-items:baseline;gap:7px;white-space:nowrap">' +
        '<span style="color:#fbbf24;font-size:14px;font-weight:700;font-variant-numeric:tabular-nums">' +
        formatTime() + '</span>' +
        '<span style="color:rgba(255,255,255,.58);font-size:11px;font-weight:500">' +
        formatTimePhase() + '</span></span>');
    }
    if (chronos.settings.trackDate) {
      clockLines.push('<span style="color:rgba(255,255,255,.72);font-size:11px;' +
        'font-weight:500;white-space:nowrap">' + formatWidgetDate() + '</span>');
    }
    if (clockLines.length) {
      sections.push('<span style="display:flex;flex-direction:column;align-items:flex-start;' +
        'gap:1px;min-width:0">' + clockLines.join('') + '</span>');
    }
    if (chronos.settings.trackWeather && validWeatherName(chronos.weather.condition)) {
      sections.push('<span style="display:flex;flex-direction:column;align-items:flex-start;' +
        'gap:1px;padding:4px 8px;border-radius:9px;background:rgba(147,197,253,.09);' +
        'border:1px solid rgba(147,197,253,.15);white-space:nowrap">' +
        '<span style="color:rgba(255,255,255,.55);font-size:10px;font-weight:600;' +
        'letter-spacing:.04em">' + displaySeason(chronos) + '</span>' +
        '<span style="color:#93c5fd;font-size:12px;font-weight:650">' +
        chronos.weather.condition + '</span></span>');
    }
    return '<div title="Current in-game time, date and weather" ' +
      'style="display:flex;flex-wrap:wrap;justify-content:center;align-items:center;' +
      'column-gap:12px;row-gap:5px;max-width:100%">' + sections.join('') + '</div>';
  }

  function appendContext(originalText) {
    var chronos = initialize();
    var text = String(originalText || '');
    if (!chronos || !chronos.settings.enabled || !hasTrackedDisplay()) return text;
    var facts = [];
    if (chronos.settings.trackTime && chronos.settings.trackDate) {
      facts.push('The current in-game time is ' + formatTimestamp() + '.');
    } else if (chronos.settings.trackTime) {
      facts.push('The current in-game time is ' + formatContextTime() + '.');
    } else if (chronos.settings.trackDate) {
      facts.push('The current in-game date is ' + formatDate() + '.');
    }
    if (chronos.settings.trackWeather && validWeatherName(chronos.weather.condition)) {
      facts.push('The current in-game weather is ' + chronos.weather.condition +
        ' in ' + displaySeason(chronos) + '.');
    }
    return facts.length ? text + '\n\n[' + facts.join(' ') + ']' : text;
  }

  function settingsTemplate(settings) {
    var value = settings || initialize().settings;
    var chronos = initialize();
    var showsWeather = value.trackWeather && validWeatherName(chronos.weather.condition);
    return [
      '# Chronos',
      'Current Values (read-only)',
      '---',
      'Current Time: ' + (value.trackTime ? formatTime() : 'Hidden'),
      'Time Phase: ' + (value.trackTime ? formatTimePhase() : 'Hidden'),
      'Current Date: ' + (value.trackDate ? formatDisplayDate() : 'Hidden'),
      'Current Season: ' + (showsWeather ? displaySeason(chronos) : 'Hidden'),
      'Current Weather: ' + (showsWeather ? chronos.weather.condition : 'Hidden'),
      '---',
      '',
      'Commands:',
      '/time 8:30 AM',
      '/date June 1, 2026 or /date June 1 (keeps the current year)',
      '/date 2026 (keeps the current month and day)',
      '/date 12/5 (keeps year; day/month in European format)',
      '/weather Rain or /weather Winter (until the next clock change)',
      '/advance 2 hours',
      '',
      'Settings (edit values after the colon)',
      '---',
      'Enabled: ' + (value.enabled ? 'On' : 'Off'),
      'Track Time: ' + (value.trackTime ? 'On' : 'Off'),
      'Track Date: ' + (value.trackDate ? 'On' : 'Off'),
      'Track Weather: ' + (value.trackWeather ? 'On' : 'Off'),
      'Minutes Per Turn: ' + value.minutesPerTurn,
      'Clock Format: ' + value.clockFormat,
      'Date Format: ' + value.dateFormat,
      '',
      '(Formats: 12-hour or 24-hour; Long, ISO (YYYY-MM-DD),',
      'American (MM/DD/YYYY), or European (DD/MM/YYYY))',
      '(Set Minutes Per Turn to 0 to stop automatic clock advancement.)',
      '(Weather follows Northern Hemisphere seasons; turn it off for custom climates.)'
    ].join('\n');
  }

  function syncSettings() {
    var chronos = initialize();
    if (!chronos) return;
    var card = findCard(SETTINGS_CARD);
    if (!card) {
      writeCard(SETTINGS_CARD, settingsTemplate(chronos.settings), 'Chronos');
      return;
    }

    var entry = cardText(card);
    var values = parseSettingsLines(entry);
    chronos.settings.enabled = parseToggle(values.enabled, chronos.settings.enabled);
    chronos.settings.trackTime = parseToggle(values.tracktime, chronos.settings.trackTime);
    chronos.settings.trackDate = parseToggle(values.trackdate, chronos.settings.trackDate);
    var wasTrackingWeather = chronos.settings.trackWeather;
    chronos.settings.trackWeather = parseToggle(
      values.trackweather,
      chronos.settings.trackWeather
    );
    if (!chronos.settings.trackWeather || !wasTrackingWeather) {
      chronos.weather.condition = null;
      chronos.weather.clock = copyClock(chronos.clock);
      chronos.weather.manual = false;
      chronos.weather.manualSeason = null;
    }
    chronos.settings.minutesPerTurn = clampInteger(
      values.minutesperturn,
      0,
      1440,
      chronos.settings.minutesPerTurn
    );
    chronos.settings.clockFormat = parseClockFormat(
      values.clockformat,
      chronos.settings.clockFormat
    );
    chronos.settings.dateFormat = parseDateFormat(
      values.dateformat,
      chronos.settings.dateFormat
    );
  }

  function publishStoryCard() {
    var chronos = initialize();
    if (!chronos) return;
    var card = findCard(SETTINGS_CARD);
    writeCard(
      SETTINGS_CARD,
      settingsTemplate(chronos.settings),
      card && card.type ? card.type : 'Chronos'
    );
  }

  function parseSettingsLines(entry) {
    var values = {};
    String(entry || '').split(/\r?\n/).forEach(function (rawLine) {
      var line = rawLine.trim();
      if (!line || line.indexOf('#') === 0 || line.indexOf(':') === -1) return;
      var separator = line.indexOf(':');
      var key = line.slice(0, separator).toLowerCase().replace(/[^a-z0-9]/g, '');
      values[key] = line.slice(separator + 1).trim();
    });
    return values;
  }

  function parseToggle(value, fallback) {
    var normalized = String(value || '').trim().toLowerCase();
    if (['on', 'true', 'yes', 'enabled'].indexOf(normalized) !== -1) return true;
    if (['off', 'false', 'no', 'disabled'].indexOf(normalized) !== -1) return false;
    return fallback;
  }

  function parseClockFormat(value, fallback) {
    var normalized = String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    if (['24', '24h', '24hour', 'military'].indexOf(normalized) !== -1) return '24-hour';
    if (['12', '12h', '12hour', 'ampm'].indexOf(normalized) !== -1) return '12-hour';
    return fallback;
  }

  function parseDateFormat(value, fallback) {
    var normalized = String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    if (['long', 'written', 'monthdayyear'].indexOf(normalized) !== -1) return 'Long';
    if (['iso', 'iso8601', 'yyyymmdd'].indexOf(normalized) !== -1) return 'ISO';
    if (['american', 'us', 'mdy', 'mmddyyyy'].indexOf(normalized) !== -1) {
      return 'American';
    }
    if (['european', 'eu', 'dmy', 'ddmmyyyy'].indexOf(normalized) !== -1) {
      return 'European';
    }
    return fallback;
  }

  function parseTime(value) {
    var match = String(value || '').trim().match(/^(\d{1,2})(?::(\d{2}))?\s*([ap]m)?$/i);
    if (!match) return null;
    var hour = Number(match[1]);
    var minute = match[2] === undefined ? 0 : Number(match[2]);
    var meridiem = String(match[3] || '').toLowerCase();
    if (minute < 0 || minute > 59) return null;
    if (meridiem) {
      if (hour < 1 || hour > 12) return null;
      if (hour === 12) hour = 0;
      if (meridiem === 'pm') hour += 12;
    } else if (hour < 0 || hour > 23) {
      return null;
    }
    return { hour: hour, minute: minute };
  }

  function parseDate(value) {
    var raw = String(value || '').trim().replace(
      /^(?:Sun(?:day)?|Mon(?:day)?|Tue(?:sday)?|Wed(?:nesday)?|Thu(?:rsday)?|Fri(?:day)?|Sat(?:urday)?)\s*,\s*/i,
      ''
    );
    var yearOnly = raw.match(/^(\d{1,6})$/);
    var iso = raw.match(/^(\d{1,6})-(\d{1,2})-(\d{1,2})$/);
    var monthName = raw.match(/^([A-Za-z]+)\s+(\d{1,2})(?:,?\s+(\d{1,6}))?$/);
    var numeric = raw.match(/^(\d{1,2})[/.](\d{1,2})(?:[/.](\d{1,6}))?$/);
    var chronos = initialize();
    var currentClock = chronos ? chronos.clock : defaultClock();
    var year;
    var month;
    var day;

    if (yearOnly) {
      year = Number(yearOnly[1]);
      month = currentClock.month;
      day = currentClock.day;
    } else if (iso) {
      year = Number(iso[1]);
      month = Number(iso[2]);
      day = Number(iso[3]);
    } else if (monthName) {
      year = monthName[3] === undefined ? currentClock.year : Number(monthName[3]);
      var requestedMonth = monthName[1].toLowerCase();
      month = MONTH_NAMES.map(function (name) { return name.toLowerCase(); })
        .findIndex(function (name) {
          return name === requestedMonth ||
            (requestedMonth.length >= 3 && name.indexOf(requestedMonth) === 0);
        }) + 1;
      day = Number(monthName[2]);
    } else if (numeric) {
      year = numeric[3] === undefined ? currentClock.year : Number(numeric[3]);
      var first = Number(numeric[1]);
      var second = Number(numeric[2]);
      var preferredFormat = chronos ? chronos.settings.dateFormat : 'Long';

      if (preferredFormat === 'American') {
        month = first;
        day = second;
      } else if (preferredFormat === 'European') {
        day = first;
        month = second;
      } else if (first > 12 && second <= 12) {
        day = first;
        month = second;
      } else if (second > 12 && first <= 12) {
        month = first;
        day = second;
      } else if (numeric[3] === undefined) {
        // Long and ISO both place month before day when the year is omitted.
        month = first;
        day = second;
      } else {
        return null;
      }
    } else {
      return null;
    }

    if (year < 1 || year > MAX_YEAR || month < 1 || month > 12) return null;
    if (day < 1 || day > daysInMonth(year, month)) return null;
    return { year: year, month: month, day: day };
  }

  function parseCommand(inputText) {
    var raw = String(inputText || '').trim()
      .replace(/^>\s*You(?:\s+say)?\s*"?/i, '')
      .replace(/[".]+\s*$/, '')
      .trim();
    var match = raw.match(/^\/([a-z]+)(?:\s+([\s\S]*))?$/i);
    if (!match) return null;
    var name = match[1].toLowerCase();
    if (['adv', 'addtime', 'skiptime', 'fastforward'].indexOf(name) !== -1) {
      name = 'advance';
    }
    if (['chronos', 'time', 'date', 'weather', 'advance'].indexOf(name) === -1) return null;
    return { name: name, argument: String(match[2] || '').trim() };
  }

  function validPendingCommand(value) {
    return isRecord(value) &&
      ['chronos', 'time', 'date', 'weather', 'advance'].indexOf(value.name) !== -1 &&
      typeof value.argument === 'string';
  }

  function handleInput(inputText) {
    var chronos = initialize();
    if (chronos) chronos.pendingCommand = null;
    var command = parseCommand(inputText);
    if (!chronos || !command) return { handled: false, text: inputText };
    chronos.pendingCommand = command;

    if (command.name === 'advance') {
      var requestedAdvance = parseAdvance(command.argument);
      return {
        handled: true,
        text: requestedAdvance
          ? 'You allow ' + requestedAdvance.label + ' to pass before continuing.'
          : 'You briefly check the Chronos time controls.'
      };
    }
    if (command.name === 'time' && !command.argument) {
      return { handled: true, text: 'You check the current time.' };
    }
    if (command.name === 'date' && !command.argument) {
      return { handled: true, text: 'You check the current date.' };
    }
    if (command.name === 'time') {
      return { handled: true, text: 'You establish the current time before continuing.' };
    }
    if (command.name === 'date') {
      return { handled: true, text: 'You establish the current date before continuing.' };
    }
    if (command.name === 'weather') {
      return { handled: true, text: 'You adjust the current weather before continuing.' };
    }
    return { handled: true, text: 'You briefly review the Chronos clock controls.' };
  }

  function applyPendingCommand() {
    var chronos = initialize();
    if (!chronos || !chronos.pendingCommand) return false;
    var command = chronos.pendingCommand;
    chronos.pendingCommand = null;

    if (command.name === 'chronos') {
      chronos.notice = 'Chronos commands: /time [8:30 AM or 20:30], ' +
        '/date [June 1, 2026, June 1, 12/5, or 2026], ' +
        '/weather [Rain or Winter], and /advance [number] ' +
        '[minutes, hours, days, or weeks]. Advance aliases: /adv, /addtime, ' +
        '/skiptime, and /fastforward. Edit the Chronos Settings Story Card ' +
        'to adjust time, date, and seasonal weather tracking.';
      return true;
    }

    if (command.name === 'time') {
      if (!command.argument) {
        chronos.notice = 'Chronos time: ' + formatContextTime() + '.';
        return true;
      }
      var parsedTime = parseTime(command.argument);
      if (!parsedTime) {
        chronos.notice = 'Chronos could not read that time. Try /time 8:30 AM or /time 20:30.';
        return true;
      }
      chronos.clock.hour = parsedTime.hour;
      chronos.clock.minute = parsedTime.minute;
      chronos.notice = 'Chronos set the time to ' + formatContextTime() + '.';
      return true;
    }

    if (command.name === 'date') {
      if (!command.argument) {
        chronos.notice = 'Chronos date: ' + formatDisplayDate() + '.';
        return true;
      }
      var parsedDate = parseDate(command.argument);
      if (!parsedDate) {
        var requestedYear = /^\d{1,6}$/.test(command.argument)
          ? Number(command.argument) : null;
        if (requestedYear && requestedYear <= MAX_YEAR &&
            chronos.clock.month === 2 && chronos.clock.day === 29 &&
            !isLeapYear(requestedYear)) {
          chronos.notice = 'Chronos cannot keep February 29 in ' + requestedYear +
            '. Enter a full date, such as /date February 28, ' + requestedYear + '.';
        } else {
          chronos.notice = 'Chronos could not read that date. Try /date June 1, 2026, ' +
            '/date June 1, /date 12/5, or /date 2026.';
        }
        return true;
      }
      chronos.clock.year = parsedDate.year;
      chronos.clock.month = parsedDate.month;
      chronos.clock.day = parsedDate.day;
      chronos.notice = 'Chronos set the date to ' + formatDisplayDate() + '.';
      return true;
    }

    if (command.name === 'weather') {
      if (!command.argument) {
        chronos.notice = 'Use /weather Sunny, Cloudy, Rain, or Snow to set weather; ' +
          '/weather Spring, Summer, Autumn, or Winter to set the season. ' +
          'The change lasts until the next clock change.';
        return true;
      }
      if (!chronos.settings.enabled || !chronos.settings.trackWeather) {
        chronos.notice = 'Turn on Chronos and Track Weather in Chronos Settings ' +
          'before using /weather.';
        return true;
      }
      var requestedCondition = WEATHER_NAMES.find(function (name) {
        return name.toLowerCase() === command.argument.toLowerCase();
      });
      var requestedSeason = SEASON_NAMES.find(function (name) {
        return name.toLowerCase() === command.argument.toLowerCase();
      });
      if (!requestedCondition && !requestedSeason) {
        chronos.notice = 'Chronos could not read that weather. ' +
          'Try /weather Rain or /weather Winter.';
        return true;
      }
      advanceWeather();
      if (requestedCondition) chronos.weather.condition = requestedCondition;
      if (requestedSeason) chronos.weather.manualSeason = requestedSeason;
      chronos.weather.manual = true;
      chronos.weather.clock = copyClock(chronos.clock);
      chronos.notice = 'Chronos set the ' + (requestedCondition ? 'weather' : 'season') +
        ' to ' + (requestedCondition || requestedSeason) + ' until the next clock change.';
      return true;
    }

    if (command.name === 'advance') {
      var advance = parseAdvance(command.argument);
      if (!advance) {
        chronos.notice = 'Chronos could not read that duration. Try /advance 30 minutes, ' +
          '/advance 4 hours, /advance 3 days, or /advance 2 weeks.';
        return true;
      }
      if (!advanceByMinutes(advance.minutes)) {
        chronos.notice = 'Chronos cannot advance beyond the supported calendar limit.';
        return true;
      }
      chronos.notice = 'Chronos advanced ' + advance.label + ' to ' +
        formatDisplayTimestamp() + '.';
      return true;
    }
    return false;
  }

  function parseAdvance(value) {
    var match = String(value || '').trim().match(
      /^(\d+)\s*(minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|wks?|w)$/i
    );
    if (!match) return null;
    var amount = Number(match[1]);
    if (!validInteger(amount) || amount <= 0) return null;
    var requestedUnit = match[2].toLowerCase();
    var unit;
    var multiplier;

    if (/^(m|mins?|minutes?)$/.test(requestedUnit)) {
      unit = 'minute';
      multiplier = 1;
    } else if (/^(h|hrs?|hours?)$/.test(requestedUnit)) {
      unit = 'hour';
      multiplier = 60;
    } else if (/^(d|days?)$/.test(requestedUnit)) {
      unit = 'day';
      multiplier = 1440;
    } else {
      unit = 'week';
      multiplier = 10080;
    }

    var minutes = amount * multiplier;
    if (!isFinite(minutes) || minutes > maxMinuteIndex()) return null;
    return {
      minutes: minutes,
      label: amount + ' ' + unit + (amount === 1 ? '' : 's')
    };
  }

  function advanceByMinutes(minutes) {
    var chronos = initialize();
    if (!chronos) return false;
    var current = clockToMinuteIndex(chronos.clock);
    if (minutes <= 0 || minutes > maxMinuteIndex() - current) return false;
    chronos.clock = clockFromMinuteIndex(current + minutes);
    return true;
  }

  function cardMatches(card, title) {
    if (!card) return false;
    if (card.title === title || card.key === title || card.keys === title) return true;
    return Array.isArray(card.keys) && card.keys.indexOf(title) !== -1;
  }

  function findCardIndex(title) {
    var cards = typeof storyCards !== 'undefined' && Array.isArray(storyCards)
      ? storyCards
      : [];
    for (var index = 0; index < cards.length; index += 1) {
      if (cardMatches(cards[index], title)) return index;
    }
    return -1;
  }

  function findCard(title) {
    var index = findCardIndex(title);
    return index >= 0 ? storyCards[index] : null;
  }

  function cardText(card) {
    if (!card) return '';
    if (card.entry !== undefined && card.entry !== null) return String(card.entry);
    if (card.value !== undefined && card.value !== null) return String(card.value);
    if (card.description !== undefined && card.description !== null) return String(card.description);
    return '';
  }

  function writeCard(title, entry, type) {
    var index = findCardIndex(title);
    if (index >= 0) {
      if (typeof updateStoryCard === 'function') {
        var card = storyCards[index] || {};
        updateStoryCard(
          index,
          card.keys || card.key || card.title || title,
          entry,
          card.type || type || 'Chronos'
        );
      }
      return;
    }
    if (typeof addStoryCard === 'function') addStoryCard(title, entry, type || 'Chronos');
  }

  function heartbeat() {
    var cards = typeof storyCards !== 'undefined' && Array.isArray(storyCards)
      ? storyCards
      : [];
    var best = null;
    var bestBeat = -1;
    for (var index = 0; index < cards.length; index += 1) {
      if (!cardMatches(cards[index], HEARTBEAT_CARD)) continue;
      try {
        var candidate = JSON.parse(cardText(cards[index]) || '{}');
        var beat = heartbeatBeat(candidate);
        if (beat > bestBeat) {
          best = candidate;
          bestBeat = beat;
        }
      } catch (error) {}
    }
    return best;
  }

  function heartbeatBeat(value) {
    var metadata = value && value.ultrascripts;
    var beat = Number(metadata && metadata.beat);
    if (!metadata || metadata.protocol !== 1 || metadata.client !== 'BetterDungeon') return -1;
    if (!metadata.enabled || metadata.archived) return -1;
    return validInteger(beat) && beat >= 0 ? beat : -1;
  }

  function observeHeartbeat() {
    var chronos = initialize();
    if (!chronos) return false;
    var value = heartbeat();
    var beat = heartbeatBeat(value);
    if (beat < 0) {
      chronos.ultrascripts.available = false;
      return false;
    }
    chronos.ultrascripts.available = chronos.ultrascripts.lastBeat === undefined ||
      beat !== chronos.ultrascripts.lastBeat;
    chronos.ultrascripts.lastBeat = beat;
    return chronos.ultrascripts.available;
  }

  function widgetAvailable() {
    var chronos = initialize();
    var value = heartbeat();
    if (!chronos || !chronos.ultrascripts.available || heartbeatBeat(value) < 0) return false;
    var modules = value && Array.isArray(value.modules) ? value.modules : [];
    for (var index = 0; index < modules.length; index += 1) {
      if (modules[index] && modules[index].id === 'widget') return true;
    }
    return false;
  }

  function readWidgetPayload() {
    var card = findCard(WIDGET_CARD);
    if (!card) return { v: 1, manifest: { widgets: [] }, history: {} };
    try {
      var parsed = JSON.parse(cardText(card) || '{}');
      if (!isRecord(parsed) || parsed.v !== 1) throw new Error('unsupported Widget state');
      if (!isRecord(parsed.manifest) || !Array.isArray(parsed.manifest.widgets)) {
        throw new Error('invalid Widget manifest');
      }
      if (!isRecord(parsed.history)) throw new Error('invalid Widget history');
      return parsed;
    } catch (error) {
      return null;
    }
  }

  function publishWidget() {
    if (!widgetAvailable()) return false;
    var payload = readWidgetPayload();
    if (!payload) return false;
    var otherWidgets = payload.manifest.widgets.filter(function (widget) {
      return widget && widget.id !== ACTIVE_WIDGET_ID;
    });
    if (otherWidgets.length > MAX_WIDGETS - 1) return false;

    payload.manifest.widgets = otherWidgets.concat([
      {
        id: ACTIVE_WIDGET_ID,
        type: 'custom',
        align: 'center',
        style: {
          display: 'inline-flex',
          padding: '7px 11px',
          borderRadius: '14px',
          background: 'rgba(20,20,26,.82)',
          border: '1px solid rgba(255,255,255,.12)',
          boxShadow: 'none'
        }
      }
    ]);

    var liveCount = currentActionCount();
    var liveKey = String(liveCount);
    var baseValues = nearestWidgetValues(payload.history, liveCount);
    var currentValues = isRecord(payload.history[liveKey])
      ? payload.history[liveKey]
      : {};
    var values = Object.assign({}, baseValues, currentValues);
    values[ACTIVE_WIDGET_ID] = { html: widgetHtml() };
    payload.history[liveKey] = values;
    pruneChronosHistory(payload.history);
    writeCard(WIDGET_CARD, JSON.stringify(payload), 'Ultrascripts');
    return true;
  }

  function nearestWidgetValues(history, liveCount) {
    var keys = Object.keys(history || {}).map(function (key) {
      return { key: key, number: Number(key) };
    }).filter(function (item) {
      return isFinite(item.number) && item.number <= liveCount;
    }).sort(function (left, right) {
      return right.number - left.number;
    });
    if (!keys.length) return {};
    var value = history[keys[0].key];
    return isRecord(value) ? value : {};
  }

  function pruneChronosHistory(history) {
    var keys = Object.keys(history || {}).map(function (key) {
      return { key: key, number: Number(key) };
    }).filter(function (item) {
      return isFinite(item.number);
    }).sort(function (left, right) {
      return right.number - left.number;
    });
    for (var index = MAX_CHRONOS_HISTORY; index < keys.length; index += 1) {
      var values = history[keys[index].key];
      if (!isRecord(values)) continue;
      delete values[ACTIVE_WIDGET_ID];
      if (Object.keys(values).length === 0) delete history[keys[index].key];
    }
  }

  function clearWidget() {
    if (!widgetAvailable()) return;
    var card = findCard(WIDGET_CARD);
    if (!card) return;
    var payload = readWidgetPayload();
    if (!payload) return;
    payload.manifest.widgets = payload.manifest.widgets.filter(function (widget) {
      return widget && widget.id !== ACTIVE_WIDGET_ID;
    });
    Object.keys(payload.history).forEach(function (key) {
      var values = payload.history[key];
      if (!isRecord(values)) return;
      delete values[ACTIVE_WIDGET_ID];
      if (Object.keys(values).length === 0) delete payload.history[key];
    });
    writeCard(WIDGET_CARD, JSON.stringify(payload), 'Ultrascripts');
  }

  function publishToast() {
    var chronos = initialize();
    if (!chronos) return;
    var parts = [];
    if (chronos.notice) parts.push(chronos.notice);
    if (chronos.settings.enabled && hasTrackedDisplay()) {
      parts.push('Chronos · ' + formatTrackedDisplay(false));
    }
    if (!parts.length) return;
    chronos.toastSequence = (chronos.toastSequence + 1) % 2;
    var uniqueMarker = chronos.toastSequence ? '\u200B' : '\u2060';
    state.message = parts.join(' ') + uniqueMarker;
    chronos.notice = '';
  }

  function clearToast() {
    if (typeof state.message === 'string' &&
        /^Chronos\b[\s\S]*[\u200B\u2060]$/.test(state.message)) {
      delete state.message;
    }
    var chronos = initialize();
    if (chronos) chronos.notice = '';
  }

  function hasNotice() {
    var chronos = initialize();
    return !!(chronos && chronos.notice);
  }

  function enabled() {
    var chronos = initialize();
    return !!(chronos && chronos.settings.enabled);
  }

  return {
    initialize: initialize,
    syncSettings: syncSettings,
    publishStoryCard: publishStoryCard,
    handleInput: handleInput,
    advanceToCurrentAction: advanceToCurrentAction,
    applyPendingCommand: applyPendingCommand,
    advanceWeather: advanceWeather,
    recordSnapshot: recordSnapshot,
    appendContext: appendContext,
    observeHeartbeat: observeHeartbeat,
    widgetAvailable: widgetAvailable,
    publishWidget: publishWidget,
    clearWidget: clearWidget,
    publishToast: publishToast,
    clearToast: clearToast,
    hasNotice: hasNotice,
    hasTrackedDisplay: hasTrackedDisplay,
    formatTime: formatTime,
    formatTimePhase: formatTimePhase,
    formatDate: formatDate,
    formatDisplayDate: formatDisplayDate,
    formatWidgetDate: formatWidgetDate,
    formatTimestamp: formatTimestamp,
    enabled: enabled,
